from pathlib import Path
import datetime,hashlib,json,subprocess,tarfile
root=Path('/data/ops-v12-native-visual-r24-20261026');r=root/'r28-worker';ns='ops-native-v12-r24-20261026'
with tarfile.open(r/'ops-r28-source-final.tgz') as t:
 dest=r/'source-final';dest.mkdir(mode=0o755);t.extractall(dest,filter='data')
def run(args):return subprocess.check_output(args,text=True).strip()
def sql(query):return json.loads(run(['docker','exec','ops-v12-native-r24-pg','psql','-X','-U','postgres','-d','ui_v12_r24_native','-Atc',query]))
positive=json.loads((r/'third-business-result.json').read_text());lifecycle=json.loads((r/'lifecycle-live-result.json').read_text());revoke=json.loads((r/'revocation-live-result.json').read_text());tenant=json.loads((root/'evidence/first-tenant.json').read_text())['tenantId'];jobs=[positive['jobId'],lifecycle['cancel']['jobId'],lifecycle['takeover']['jobId'],revoke['revocation']['jobId']]
assert all(len(j)==36 and all(c in '0123456789abcdef-' for c in j) for j in jobs)
ids=','.join("'"+j+"'" for j in jobs)
records=sql("SELECT json_agg(json_build_object('jobId',j.job_id,'state',j.state,'errorCode',j.error_code,'epoch',q.fencing_epoch,'policyVersion',j.policy_version,'authoritySource',j.assistant_binding->>'authorizationSource','authorizationUserId',j.assistant_binding->>'authorizationUserId','authorizationVersion',j.assistant_binding->>'authorizationVersion','modelProfileVersion',j.assistant_binding->>'modelProfileVersion','budgetConsumed',j.budget_consumed,'steps',(SELECT json_agg(json_build_object('stepId',s.step_id,'tool',s.tool_name,'state',s.state,'errorCode',s.error_code,'responseId',CASE WHEN s.tool_name='model' THEN s.result->'response'->>'id' END,'returnedModel',CASE WHEN s.tool_name='model' THEN s.result->'response'->>'model' END,'providerUsage',CASE WHEN s.tool_name='model' THEN s.result->'response'->'usage' END)) FROM investigation.steps s WHERE s.tenant_id=j.tenant_id AND s.job_id=j.job_id),'contexts',(SELECT json_agg(json_build_object('contextId',c.context_id,'audience',c.audience,'generation',c.lease_generation)) FROM investigation.contexts c WHERE c.tenant_id=j.tenant_id AND c.job_id=j.job_id))) FROM investigation.jobs j JOIN investigation.worker_queue q USING(tenant_id,job_id) WHERE j.tenant_id='"+tenant+"' AND j.job_id IN("+ids+")")
pods=json.loads(run(['kubectl','-n',ns,'get','pods','ops-api','ops-worker','ops-investigator','-o','json']))
public={'date':datetime.datetime.now(datetime.timezone.utc).isoformat(),'namespace':ns,'origin':'https://192.168.0.63:30471','schema':sql('SELECT max(version_id) FROM goose_db_version WHERE is_applied'),'jobs':records,'pods':[{'name':p['metadata']['name'],'uid':p['metadata']['uid'],'ready':all(c.get('ready') for c in p['status'].get('containerStatuses',[])),'images':[c.get('imageID') for c in p['status'].get('containerStatuses',[])]} for p in pods['items']],'apiSHA256':hashlib.sha256((r/'ops-api-query').read_bytes()).hexdigest(),'workerSHA256':hashlib.sha256((r/'ops-worker').read_bytes()).hexdigest(),'sourceArchiveSHA256':hashlib.sha256((r/'ops-r28-source-final.tgz').read_bytes()).hexdigest(),'billingNote':'token budgets are enforced; interrupted calls conservatively consume reservations; modelCostMicros is an unpriced legacy field, not a zero-charge assertion','releaseScope':'source canary in existing exact images; not a rebuilt signed OCI/Bundle acceptance'}
(r/'final-runtime.json').write_text(json.dumps(public,ensure_ascii=False,indent=2)+'\n');print('final runtime/source/Job/Step/context metadata captured; no credentials or prompt/response contents exported')
